nav-cards.css:
.nav-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }
}

/* Auto-fits 185–210px cards, wrapping as needed. */
.nav-cards-grid.nav-cards-grid--numbered {
  grid-template-columns: repeat(auto-fit, minmax(185px, 210px));
  justify-content: center;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }
}

.nav-card {
  background-color: var(--secondary-colour);
  border-top: 6px solid var(--primary-colour);
  border-radius: 0 0 10px 10px;
  padding: 1.75rem 1.5rem;
  text-align: left;

  .nav-card__icon {
    width: 76px;
    height: 76px;
    border-radius: 50%;
    background-color: var(--primary-colour);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.25rem;

    img {
      width: 34px;
      height: 34px;
      display: block;
    }
  }

  p {
    margin: 0 0 1.25rem;
    color: var(--card-text-colour);
    font-weight: 500;
  }

  .nav-card__button {
    display: block;
    width: 100%;
    text-align: center;
    background: var(--primary-colour);
    color: var(--text-on-primary) !important;
    font-weight: 700;
    text-decoration: none !important;
    padding: 0.6rem 2rem;
    border-radius: 15px;

    &:hover {
      background: color-mix(in srgb, var(--primary-colour), black 15%);
      text-decoration: none;
    }
  }

  &.nav-card--numbered {
    display: flex;
    flex-direction: column;
    position: relative;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
    max-width: 210px;
    min-width: 185px;
    padding: 16px;

    &:hover {
      transform: translateY(-3px);
      box-shadow: 0 8px 16px color-mix(in srgb, var(--shadow-colour) 15%, transparent);
    }

    h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--card-text-colour);
      margin: 0;
    }

    .nav-card__number {
      color: var(--primary-colour);
    }

    .nav-card__icon-plain {
      margin-top: auto;
      padding-top: 1.5rem;

      img {
        width: 78px;
        height: 78px;
        object-fit: contain;
        display: block;
      }
    }

    @media (max-width: 768px) {
      flex-direction: row;
      align-items: center;
      max-width: none;
      min-width: 0;

      h3 {
        flex: 1;
      }

      .nav-card__icon-plain {
        margin-top: 0;
        padding-top: 0;
        margin-left: 1rem;
        flex-shrink: 0;
      }
    }
  }
}

at-a-glance.css:
#at-a-glance {
  background-color: var(--panel-background);
  border-bottom: 4px solid var(--primary-colour);
  border-radius: 20px 20px 0 0;
  padding: 20px;

  @media (max-width: 768px) {
    order: 2;
  }

  #at-a-glance-heading {
    margin-block: 0 10px;
    font-size: 18px;
    font-weight: bold;
    color: var(--primary-colour);
  }

  ul {
    margin-block: 0;

    li + li {
      margin-top: 10px;
    }
  }
}

image-text-section.css:
.image-text-section {
  > img,
  > iframe {
    float: right;
    width: 100%;
    max-width: 275px;
    margin: 0 0 1rem 1.5rem;
    border-radius: 16px;
  }

  > iframe {
    aspect-ratio: 16 / 9;
    height: auto;
    border: none;
  }

  > img.media-large {
    width: 340px;
    max-width: 45%;
  }

  > div {
    min-width: 0;
  }

  &::after {
    content: "";
    display: block;
    clear: both;
  }

  h3 {
    color: var(--primary-colour);
    font-size: var(--numbered-subheading);
    font-weight: 600;
  }

  @media (max-width: 768px) {
    margin-top: 0;

    > img,
    > iframe {
      float: none;
      display: block;
      max-width: none;
      width: 100%;
      margin: 0 auto 1rem;
    }

    > img {
      aspect-ratio: 3 / 2;
      object-fit: cover;
      object-position: top;
      margin: 0 auto 1rem;
    }

    > img.media-large {
      float: right;
      display: inline;
      width: 200px;
      max-width: 40%;
      aspect-ratio: auto;
      object-fit: initial;
      margin: 0 0 1.5rem 2.5rem;
    }
  }
}

accordion.css:
.accordion {
  margin-block: 1rem 1.5rem;

  .accordion-header {
    margin: 0;
  }

  .accordion-item {
    border: none !important;
  }

  .accordion-button {
    color: var(--primary-colour) !important;
    background-color: transparent !important;
    padding: 0.5rem 0 !important;
    box-shadow: none !important;
    font-weight: 600;

    .accordion-button-text {
      text-decoration: underline;
    }

    &:hover .accordion-button-text {
      text-decoration: none;
    }

    /* The block removes Bootstrap's focus shadow, so keyboard focus needs its own ring. */
    &:focus-visible {
      outline: 3px solid var(--focus-ring-colour);
      outline-offset: 4px;
      position: relative;
      z-index: 2;
    }

    &::after {
      display: none;
    }

    &::before {
      content: "▸";
      scale: 2;
      margin-right: 8px;
      transition: transform 0.2s ease-in-out;
      color: var(--primary-colour);
    }

    &:not(.collapsed) {
      background-color: transparent !important;
      color: var(--primary-colour) !important;
      box-shadow: none !important;

      &::before {
        transform: rotate(90deg);
      }
    }
  }

  .accordion-body {
    padding: 1rem 0;
  }
}

icon-toggle.css:
.data-icons-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-block: 1.5rem;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }

  h5 {
    font-size: 14px;
    margin: 0.5rem 0 0;
    color: var(--primary-colour);
    font-weight: 600;
  }
}

.data-icon-trigger {
  cursor: pointer;
}

.data-icon-card {
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border: 1px solid var(--tile-border-colour);
  border-radius: 15px;
  padding: 0.5rem 0.2rem;
  text-align: center;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;

  &:hover {
    transform: translateY(-3px);
    box-shadow: 0 4px 8px color-mix(in srgb, var(--shadow-colour) 25%, transparent);
  }

  &.active {
    border: 3px solid var(--primary-colour);
    box-shadow: 0 0.5rem 1rem color-mix(in srgb, var(--shadow-colour) 15%, transparent);
  }

  img {
    width: 45px;
  }
}

.content-display {
  display: none;
  margin-block: 1rem;
  padding: 1.2rem;
  border: 2px solid var(--primary-colour);
  background-color: transparent;
  border-radius: 12px;
  /* Extra offset so the clicked icon stays visible above the panel. */
  scroll-margin-top: calc(var(--anchor-section-offset, 145px) + 110px);

  &.active {
    display: block;
  }
}

.content-display-inner-grid {
  display: grid;
  grid-template-columns: 3fr 1fr;
  gap: 2rem;
  align-items: center;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;

    img {
      order: -1;
    }
  }

  img {
    width: 110px;
    height: auto;
    justify-self: center;
  }
}

icon-toggle.js:
function openAccordion(tileColumn, contentId) {
  const tile = tileColumn.querySelector(".data-icon-card");
  const openContent = document.querySelector(".content-display.active");
  const activeTile = document.querySelector(".data-icon-card.active");
  if (openContent && openContent.id !== contentId) {
    openContent.classList.remove("active");
    openContent.style.display = "none";
  }
  if (activeTile && activeTile !== tile) {
    activeTile.classList.remove("active");
  }
  const content = document.getElementById(contentId);
  if (content.style.display === "block") {
    content.style.display = "none";
    content.classList.remove("active");
    tile.classList.remove("active");
  } else {
    content.style.display = "block";
    content.classList.add("active");
    tile.classList.add("active");
    if (window.innerWidth <= 768) {
      tileColumn.insertAdjacentElement("afterend", content);
    }
    content.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
  }
}
function openAccordionKey(event, tileColumn, contentID) {
  if (event.key === "Enter") {
    openAccordion(tileColumn, contentID);
  }
}

resource-cards.css:
.cards-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  justify-items: center;
  align-items: stretch;
  gap: 1rem;

  @media (max-width: 576px) {
    grid-template-columns: repeat(1, 90%);
    justify-content: center;
  }

  .card {
    display: flex;
    flex-direction: column;
    width: 100%;
    border-radius: 10px;
    box-shadow: 0 4px 8px color-mix(in srgb, var(--shadow-colour) 50%, transparent);
    transition: 0.2s;

    &:hover {
      transform: translateY(-3px);
      box-shadow: 8px 12px 29px -3px color-mix(in srgb, var(--shadow-colour) 40%, transparent);
    }

    @media (max-width: 576px) {
      max-width: 300px;
    }

    > div {
      flex: 1;
      padding: 1rem 1rem 0 1rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 180px;

      > a {
        margin-bottom: 2rem;
        color: var(--primary-colour);
      }
    }

    p {
      display: flex;
      justify-content: space-between;
    }
  }

  .resource-card__img {
    width: 100%;
    height: auto;
    object-fit: cover;
    border-radius: 10px 10px 0 0;
  }
}

buttons.css:
.buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;

  a {
    display: inline-block;
    width: 250px;
    max-width: 100%;
    text-align: center;
    background: var(--primary-colour);
    color: var(--text-on-primary) !important;
    padding: 14px 28px;
    border-radius: 10px;
    text-decoration: none !important;
    font-weight: 600;
    transition: 0.2s;

    &:hover {
      background: color-mix(in srgb, var(--primary-colour), black 15%);
      text-decoration: none;
    }
  }
}

.flex-section .buttons,
.two-column .buttons {
  flex-direction: column;
  align-items: stretch;
  margin-top: 1.5rem;
}

.flex-section .buttons a,
.two-column .buttons a {
  max-width: none;
  width: 100%;
}

flex-section.css:
.flex-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3rem;

  @media (max-width: 768px) {
    flex-direction: column;
  }
}

.text-content {
  flex: 1;
  min-width: 0;
}

.video-content {
  flex: 1;
  display: flex;
  justify-content: flex-end;

  @media (max-width: 768px) {
    justify-content: center;
    order: -1;
  }

  img {
    width: 100%;
    max-width: 320px;
    height: auto;
    display: block;
    border-radius: 16px;

    @media (max-width: 768px) {
      aspect-ratio: 3 / 2;
      object-fit: cover;
      object-position: top;
      max-width: 100%;
      margin: 0 auto;
    }
  }

  iframe {
    width: 100%;
    aspect-ratio: 16 / 9;
    height: auto;
    border-radius: 16px;
    border: none;
  }
}

two-column.css:
.two-column {
  display: flex;
  align-items: flex-start;
  gap: 2rem;

  @media (max-width: 768px) {
    flex-direction: column;
    align-items: stretch;
    gap: 1.5rem;
  }

  @media (min-width: 769px) {
    &.two-column--flipped {
      flex-direction: row-reverse;
    }
  }
}

.two-column__media {
  flex: 0.8 1 0;
  min-width: 0;
}

.two-column__content {
  flex: 1 1 0;
  min-width: 0;
}

.two-column__media img,
.two-column__media iframe {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 16px;
}

.two-column__media iframe {
  aspect-ratio: 16 / 9;
  border: none;
}

@media (min-width: 769px) {
  .two-column__media {
    margin-top: 1.5rem;
  }
}

@media (max-width: 768px) {
  .two-column__media img {
    aspect-ratio: 3 / 2;
    object-fit: cover;
    object-position: top;
    margin: 0 auto;
  }
}
